package connect

// ResultOf determines the winner of a game of Hex / Polygon / CON-TAC-TIX.
//
// The board is given as a slice of strings, one per row, where each cell
// holds 'X', 'O' or '.' (empty). The board is a parallelogram of hexagonal
// cells: each row is shifted right by half a cell relative to the row above
// it, so cell (r, c) sits at character position r + 2c.
//
// Player 'O' connects from the top edge to the bottom edge.
// Player 'X' connects from the left edge to the right edge.
// The first player to form an unbroken line of their own stones between the
// two opposite edges wins. If neither has, the result is "".
func ResultOf(lines []string) (string, error) {
	rows := len(lines)
	if rows == 0 {
		return "", nil
	}

	grid := make([][]rune, rows)
	for r, line := range lines {
		grid[r] = []rune(line)
	}

	// The six hexagonal neighbours of a cell in the parallelogram layout.
	// Cell (r, c) touches the cell to its left and right, plus the two cells
	// in each adjacent row that are offset by half a cell.
	var neighborDeltas = [6][2]int{
		{0, 1},   // right
		{0, -1},  // left
		{1, 0},   // down
		{1, -1},  // down-left
		{-1, 1},  // up
		{-1, 0},  // up-left
	}

	// onEdge reports whether cell (r, c) lies on the named edge of the board.
	onEdge := func(r, c int, edge string) bool {
		switch edge {
		case "top":
			return r == 0
		case "bottom":
			return r == rows-1
		case "left":
			return c == 0
		case "right":
			return c == len(grid[r])-1
		}
		return false
	}

	// connects reports whether the player's stones form an unbroken path from
	// the start edge to the end edge, using a breadth-first search seeded with
	// every one of the player's stones on the start edge.
	connects := func(player rune, startEdge, endEdge string) bool {
		visited := make([][]bool, rows)
		for r := range visited {
			visited[r] = make([]bool, len(grid[r]))
		}

		var queue [][2]int
		for r := 0; r < rows; r++ {
			for c := 0; c < len(grid[r]); c++ {
				if grid[r][c] == player && onEdge(r, c, startEdge) {
					visited[r][c] = true
					queue = append(queue, [2]int{r, c})
				}
			}
		}

		for len(queue) > 0 {
			cur := queue[0]
			queue = queue[1:]
			r, c := cur[0], cur[1]

			if onEdge(r, c, endEdge) {
				return true
			}

			for _, d := range neighborDeltas {
				nr, nc := r+d[0], c+d[1]
				if nr < 0 || nr >= rows || nc < 0 || nc >= len(grid[nr]) {
					continue
				}
				if visited[nr][nc] || grid[nr][nc] != player {
					continue
				}
				visited[nr][nc] = true
				queue = append(queue, [2]int{nr, nc})
			}
		}
		return false
	}

	// O plays top to bottom; X plays left to right. The two connections are
	// mutually exclusive, so at most one can succeed.
	if connects('O', "top", "bottom") {
		return "O", nil
	}
	if connects('X', "left", "right") {
		return "X", nil
	}
	return "", nil
}

